import{_ as e,o as r,c as t,a2 as o}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"焰种","description":"","frontmatter":{},"headers":[],"relativePath":"表层/种族/焰种.md","filePath":"表层/种族/焰种.md","lastUpdated":1787065118000}'),l={name:"表层/种族/焰种.md"};function i(h,a,n,s,d,c){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="焰种" tabindex="-1">焰种 <a class="header-anchor" href="#焰种" aria-label="Permalink to &quot;焰种&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>焰种是传说中的种族，只存在于某些古代文献的只言片语之中，内容十分有限。焰种是否真的存在过，至今没有确切答案。</p><hr><h2 id="已知记载" tabindex="-1">已知记载 <a class="header-anchor" href="#已知记载" aria-label="Permalink to &quot;已知记载&quot;">​</a></h2><h3 id="出现" tabindex="-1">出现 <a class="header-anchor" href="#出现" aria-label="Permalink to &quot;出现&quot;">​</a></h3><p>据古代文献记载，在一次大灾难（<strong>天穹破碎</strong>）之后，焰种在一片区域内有过出现。</p><h3 id="形态传闻" tabindex="-1">形态传闻 <a class="header-anchor" href="#形态传闻" aria-label="Permalink to &quot;形态传闻&quot;">​</a></h3><p>焰种的形态传闻好似一团飞舞的火焰。</p><h3 id="词义演变" tabindex="-1">词义演变 <a class="header-anchor" href="#词义演变" aria-label="Permalink to &quot;词义演变&quot;">​</a></h3><p>焰种被宣传为邪恶异种，从未以&quot;族&quot;相称。随着历史发展，&quot;焰种&quot;一词逐渐演变出<strong>叛徒、异类</strong>等贬义。</p><hr><h2 id="现状" tabindex="-1">现状 <a class="header-anchor" href="#现状" aria-label="Permalink to &quot;现状&quot;">​</a></h2><p>除上述古代文献的只言片语外，没有任何关于焰种的现存记载。更多信息待后续补充。</p><hr><h2 id="深层真相" tabindex="-1">深层真相 <a class="header-anchor" href="#深层真相" aria-label="Permalink to &quot;深层真相&quot;">​</a></h2><blockquote><p>焰种的真实来历与天穹破碎事件的真相不属表层认知。</p></blockquote><ul><li><a href="./../../中层/世界/太空巨构" class="layer-link" data-layer="中层">太空巨构</a></li><li><a href="./../../中层/世界/太空清除计划" class="layer-link" data-layer="中层">太空清除计划</a></li><li><a href="./../历史/共同体时期">共同体时期</a></li></ul><hr>',19)])])}const _=e(l,[["render",i]]);export{p as __pageData,_ as default};
